import type { ComponentType, ReactNode } from 'react'

/**
 * The two things breadcrumbs need from a router, supplied by you.
 *
 * Kept as an injected adapter rather than importing a router directly, so the
 * same item works under Next.js, React Router, TanStack Router, or none of
 * them — and so installing it never drags in a routing library you don't use.
 */
export interface RouterAdapter {
  /** Current path. Used to re-assert the trail on navigation. */
  useCurrentPath: () => string
  Link: ComponentType<{
    href: string
    className?: string
    onClick?: () => void
    children: ReactNode
  }>
}

/** React Router:
 * ```tsx
 * const adapter: RouterAdapter = {
 *   useCurrentPath: () => useLocation().pathname,
 *   Link: ({ href, ...props }) => <RouterLink to={href} {...props} />,
 * }
 * ```
 *
 * Next.js:
 * ```tsx
 * const adapter: RouterAdapter = {
 *   useCurrentPath: usePathname,
 *   Link: ({ href, ...props }) => <NextLink href={href} {...props} />,
 * }
 * ```
 */

import type {
  Breadcrumb,
  BreadcrumbRouteConfig,
  BreadcrumbRouteNode,
} from '../types/breadcrumbs'

/**
 * Builds a breadcrumb tree where every node already knows its full trail.
 *
 * Declaring the hierarchy once, separately from the route table, is what makes
 * this work: a screen says *where it is* rather than *what its trail is*, so
 * moving a route re-parents its breadcrumbs automatically and no screen can
 * drift out of sync with the nesting.
 *
 * ```ts
 * export const breadcrumbsRouter = createBreadcrumbRouter({
 *   home: {
 *     key: 'home',
 *     component: <BreadcrumbLink url="/" label="Home" />,
 *     routes: {
 *       organization: {
 *         key: 'organization',
 *         component: <OrganizationBreadcrumb />,
 *       },
 *     },
 *   },
 * })
 *
 * // in the organization layout:
 * <Breadcrumbs.Setter node={breadcrumbsRouter.home.organization} />
 * ```
 */
export function createBreadcrumbRouter<
  T extends Record<string, BreadcrumbRouteConfig>,
>(
  config: T,
  ancestors: Breadcrumb[] = []
): { [K in keyof T]: BreadcrumbRouteNode<NonNullable<T[K]['routes']>> } {
  return Object.fromEntries(
    Object.entries(config).map(([key, node]) => {
      const crumb: Breadcrumb = { key: node.key, component: node.component }
      const _breadcrumbs = [...ancestors, crumb]
      const children = node.routes
        ? createBreadcrumbRouter(node.routes, _breadcrumbs)
        : {}
      return [key, { key: node.key, component: node.component, _breadcrumbs, ...children }]
    })
  ) as { [K in keyof T]: BreadcrumbRouteNode<NonNullable<T[K]['routes']>> }
}

import type { Breadcrumb, BreadcrumbRouteNode } from '../types/breadcrumbs'

/** Minimal structural `set` — compatible with zustand's `StateCreator` set. */
export type SetLike<TStore> = (
  partial: Partial<TStore> | ((state: TStore) => Partial<TStore>)
) => void

export interface BreadcrumbsSliceState {
  /**
   * Prepended to every trail. Useful for a persistent root ("Home", a tenant
   * switcher) that shouldn't be repeated in every route declaration.
   */
  breadcrumbs_leadingBreadcrumb?: Breadcrumb
  breadcrumbs_raw: Array<Breadcrumb>
}

export interface BreadcrumbsSliceActions {
  breadcrumbsActions: {
    setLeadingBreadcrumb: (breadcrumb?: Breadcrumb) => void
    setBreadcrumbs: (breadcrumbs: Array<Breadcrumb>) => void
    /** Takes a node from `createBreadcrumbRouter` and adopts its whole trail. */
    setBreadcrumbsFromRouter: (
      node: Pick<BreadcrumbRouteNode, '_breadcrumbs'>
    ) => void
  }
  breadcrumbsGetters: {
    /** The trail as rendered: leading crumb first, when set. */
    getBreadcrumbs: () => Array<Breadcrumb>
  }
}

export type BreadcrumbsSlice = BreadcrumbsSliceState & BreadcrumbsSliceActions

/**
 * Store-agnostic slice creator — spread into any zustand store:
 *
 * ```ts
 * const useAppStore = create<AppStore>()((set, get) => ({
 *   ...createBreadcrumbsSlice<AppStore>()(set, get),
 * }))
 * ```
 */
export const createBreadcrumbsSlice =
  <TStore extends BreadcrumbsSlice>() =>
  (set: SetLike<TStore>, get: () => TStore): BreadcrumbsSlice => {
    const write = (partial: Partial<BreadcrumbsSliceState>) =>
      set(partial as Partial<TStore>)

    return {
      breadcrumbs_leadingBreadcrumb: undefined,
      breadcrumbs_raw: [],

      breadcrumbsActions: {
        setLeadingBreadcrumb: (breadcrumbs_leadingBreadcrumb) =>
          write({ breadcrumbs_leadingBreadcrumb }),
        setBreadcrumbs: (breadcrumbs_raw) => write({ breadcrumbs_raw }),
        setBreadcrumbsFromRouter: (node) =>
          write({ breadcrumbs_raw: node._breadcrumbs }),
      },

      breadcrumbsGetters: {
        getBreadcrumbs: () => {
          const { breadcrumbs_leadingBreadcrumb, breadcrumbs_raw } = get()
          return breadcrumbs_leadingBreadcrumb
            ? [breadcrumbs_leadingBreadcrumb, ...breadcrumbs_raw]
            : [...breadcrumbs_raw]
        },
      },
    }
  }

'use client'

import { ChevronRight } from 'lucide-react'
import React, { useEffect } from 'react'

import type { BreadcrumbsSlice } from '../lib/breadcrumbs-slice'
import type { BreadcrumbRouteNode } from '../types/breadcrumbs'
import type { RouterAdapter } from '../types/router-adapter'

/** Structural shape of a zustand hook (`UseBoundStore<StoreApi<T>>`). */
export interface StoreHookLike<TStore> {
  <TReturn>(selector: (state: TStore) => TReturn): TReturn
}

/**
 * Binds the breadcrumb components to your store and router once:
 *
 * ```ts
 * export const Breadcrumbs = createBreadcrumbs(useAppStore, routerAdapter)
 * ```
 *
 * A factory rather than hardcoded imports, so the item needs to know neither
 * where your store lives nor which router you use.
 */
export function createBreadcrumbs<TStore extends BreadcrumbsSlice>(
  useStore: StoreHookLike<TStore>,
  router: RouterAdapter
) {
  function Breadcrumbs() {
    const breadcrumbs = useStore((s) => s.breadcrumbsGetters.getBreadcrumbs())

    return (
      <div className="min-w-0">
        <div className="flex items-end gap-1 overflow-x-auto whitespace-nowrap">
          {breadcrumbs.map((crumb, i) => (
            <React.Fragment key={crumb.key}>
              {crumb.component}
              <div className="flex h-[28px] items-center">
                {i + 1 < breadcrumbs.length && <ChevronRight size={16} />}
              </div>
            </React.Fragment>
          ))}
        </div>
      </div>
    )
  }

  /**
   * Declares where the current screen sits. Renders nothing.
   *
   * Put it in the layout for a route rather than in the page body, so the trail
   * is set by the nesting that is actually mounted.
   */
  function Setter({ node }: { node: Pick<BreadcrumbRouteNode, '_breadcrumbs'> }) {
    const setBreadcrumbsFromRouter = useStore(
      (s) => s.breadcrumbsActions.setBreadcrumbsFromRouter
    )
    const path = router.useCurrentPath()

    useEffect(() => {
      setBreadcrumbsFromRouter(node)
      // Depends on the path as well as the node: a layout can stay mounted
      // across a route change within its own subtree, and the trail still has
      // to be reasserted when a deeper layout unmounts.
    }, [path, node, setBreadcrumbsFromRouter])

    return null
  }

  Breadcrumbs.Setter = Setter
  return Breadcrumbs
}

'use client'

import { CheckIcon, ChevronsUpDownIcon } from 'lucide-react'
import { ReactNode, useState } from 'react'

import { Button } from '@/components/ui/button'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { Spinner } from '@/components/ui/spinner'
import { cn } from '@/lib/utils'

import type { RouterAdapter } from '../types/router-adapter'

export interface BreadcrumbEntity {
  name: string
  id: string
  url: string
  icon?: ReactNode
}

export interface EntityBreadcrumbProps {
  label: string
  entities: Array<BreadcrumbEntity>
  currentlySelectedId: string
  isLoading?: boolean
  /** Same adapter you passed to `createBreadcrumbs`. */
  Link: RouterAdapter['Link']
}

/**
 * A breadcrumb segment that is also a switcher — it names the current entity
 * and opens a searchable list of its siblings.
 *
 * Wrap it per entity type in your app to supply `entities` from wherever that
 * list lives:
 *
 * ```tsx
 * export function ProjectBreadcrumb() {
 *   const { projectId } = useParams()
 *   const projects = useAppStore((s) => s.project_list) ?? []
 *   return (
 *     <EntityBreadcrumb
 *       label="Project"
 *       currentlySelectedId={projectId ?? ''}
 *       entities={projects.map((p) => ({
 *         id: String(p.id),
 *         name: p.name,
 *         url: `/project/${p.id}`,
 *       }))}
 *     />
 *   )
 * }
 * ```
 */
export function EntityBreadcrumb({
  entities,
  label,
  currentlySelectedId,
  isLoading,
  Link,
}: Readonly<EntityBreadcrumbProps>) {
  const [open, setOpen] = useState(false)

  const selected = entities.find((e) => e.id === currentlySelectedId)
  // Selected entity floated to the top so the current item is always the first
  // thing under the cursor when the list opens.
  const ordered = entities.toSorted((a) =>
    a.id === currentlySelectedId ? -1 : 1
  )

  return (
    <div className="flex flex-col gap-1">
      <p className="text-muted-foreground text-xs font-medium">{label}</p>
      {isLoading ? (
        <Button variant="outline" className="justify-between" size="sm" disabled>
          <Spinner />
          <ChevronsUpDownIcon className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      ) : (
        <Popover open={open} onOpenChange={setOpen}>
          <PopoverTrigger asChild>
            <Button
              variant="outline"
              role="combobox"
              aria-expanded={open}
              className="justify-between"
              size="sm"
            >
              {selected?.icon}
              <span className="truncate">{selected?.name}</span>
              <ChevronsUpDownIcon className="ml-2 h-4 w-4 shrink-0 opacity-50" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-auto p-0">
            <Command>
              <CommandInput
                placeholder={`Search for ${label.toLowerCase()}...`}
                className="h-8"
              />
              <CommandList>
                <CommandEmpty>No results found.</CommandEmpty>
                <CommandGroup>
                  {ordered.map((item) => (
                    // value includes the id so two entities with the same name
                    // remain independently selectable in the filter.
                    <CommandItem
                      key={item.id}
                      value={`${item.name}-${item.id}`}
                      asChild
                    >
                      <Link
                        href={item.url}
                        onClick={() => setOpen(false)}
                        className="flex gap-1 text-xs"
                      >
                        {item.icon}
                        {item.name}
                        <CheckIcon
                          className={cn(
                            'ml-auto h-4 w-4',
                            item.id === currentlySelectedId
                              ? 'opacity-100'
                              : 'opacity-0'
                          )}
                        />
                      </Link>
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
            </Command>
          </PopoverContent>
        </Popover>
      )}
    </div>
  )
}
